//! The checked-ambient artifact (slices one and two): the pre-resolved,
//! pre-declared, pre-declared-hard tables of the ambient member, beside
//! [`ambient_blob`](crate::ambient_blob)'s pre-expanded tree.
//!
//! The artifact is a checked-in postcard payload (`src/ambient.dsi`,
//! regenerated by the `gen-ambient-dsi` example) behind the same
//! 16-byte source-hash header discipline as the AST blob: a stale header
//! or a foreign file id is a cache miss, and every caller falls back to
//! the fresh compute, so the artifact is a pure cache, never
//! correctness-load-bearing. It carries, for the ambient member alone:
//!
//! * the resolve half — the package namespace parts and the member's resolution table — so a served
//!   run collects and resolves only the user files, continuing the ambient's
//!   [`DefId`](ds_check::DefId) and [`MethodId`](ds_check::MethodId) spaces exactly as a fresh run
//!   mints them (the mint-determinism pin);
//! * the declaration half's plain tables — the universe's atom and trait mint logs (replayed
//!   through the declare APIs) plus the atoms/structs/enums/cases tables and the trait memberships
//!   — so the reserve and shape passes skip the served defs;
//! * the hard declaration tables — every stored signature (`fns`, trait `members`, `inherent`; the
//!   embedded written types serialize like the AST blob's trees), the trait member/generics tables,
//!   the instance environment's rows with their solved heads and conditions (raw
//!   [`Ty`](ds_check::Ty) indices valid because the interned-set log replays in intern order and
//!   the mint log pins the atom space), the impl-item ties, and the shape-phase atom mints the
//!   skipped impl arms would have performed — so the ambient's own impl items skip their instance
//!   declarations and the closure coherence pass probes only the fresh rows (the artifact's clean
//!   generation proved the served prefix coherent against a byte-identical universe, and its heads
//!   carry no trait-relative node a later membership could widen);
//! * the effects half's solved rows — the ambient's definitions' and registered methods' fixpoint
//!   rows, computed against this crate's own [`declared_rows`](crate::declared_rows) and
//!   [`world_caps`](crate::world_caps) tables — so a served run walks only the user trees and seeds
//!   the ambient's subgraph as fixed inputs (the ambient's bodies name only ambient names, so its
//!   fixpoint solution is independent of the user half).
//!
//! Everything the artifact serves stays fresh somewhere by ruling or by
//! reach: the checked body facts stay fresh by G3.5's ruling, and the
//! solved span-keyed records (`trait_impl_args`, `inherent_impl_bounds`,
//! `impl_fn_rets`) rebuild over the blob-served trees.
//!
//! The drift gates pin the artifact three ways: a byte gate re-generates
//! from the current source and compares postcard bytes; an equivalence
//! gate runs the served analyze and the fresh analyze over the same
//! ambient-plus-user program and deep-compares the bundles (trees,
//! namespace, resolutions, universe, declaration tables, signature
//! tables, instance rows, solved records, checked facts, effect rows);
//! and the run-path suite exercises the served path end to end, since
//! the CLI takes it by default on every cold compile.

use std::{collections::HashMap, sync::Arc};

use ds_check::{
    Analyzed, AtomKind, Case, Condition, Def, DefEffects, DefId, DefKind, Effects, Field, FnSig,
    InstanceId, MethodDecl, MethodId, MethodOwner, Package, ReplayMint, Res, Resolutions,
    ServedDecls, ServedInstance, ServedMethodRow, TraitId, TypeExpr, TypeId, Universe,
};
use ds_diag::{FileId, Span};
use ds_mod::Hash128;
use serde::{Deserialize, Serialize};

/// The embedded artifact: source-hash header plus the postcard-encoded
/// tables.
static DSI: &[u8] = include_bytes!("ambient.dsi");

/// The source-hash header's size in bytes.
const HEADER: usize = 16;

/// Why the checked-ambient artifact could not be served.
#[derive(Debug)]
pub enum AmbientDsiError {
    /// The artifact's source hash does not match `AMBIENT_SOURCE`: the
    /// artifact predates a source edit. Regenerate it with the
    /// `gen-ambient-dsi` example.
    SourceDrift,
    /// The artifact addresses a different file than the caller
    /// registered: its spans carry the file id it was generated with, so
    /// only a first-registered ambient can take the direct hit.
    FileMismatch,
    /// The payload failed to decode, or decoded to tables the conversion
    /// refuses (an unknown discriminant): a corrupt artifact, answered
    /// like every other miss.
    Decode(&'static str),
}

impl std::fmt::Display for AmbientDsiError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            Self::SourceDrift => f.write_str("the checked-ambient artifact is stale"),
            Self::FileMismatch => {
                f.write_str("the checked-ambient artifact addresses another file id")
            },
            Self::Decode(why) => write!(f, "the checked-ambient artifact is corrupt: {why}"),
        }
    }
}

impl std::error::Error for AmbientDsiError {}

/// The decoded artifact's native serve, ready for the ds-check entries:
/// the namespace parts and resolution table
/// ([`analyze_served`](ds_check::type_of::analyze_served)'s inputs), the
/// declaration prefix
/// ([`ServedDecls`]' replay input), and the solved effect rows
/// ([`effects_of_resolved_served`](ds_check::effects::effects_of_resolved_served)'s
/// seeds).
pub struct ServedAmbient {
    /// The ambient member's collected namespace.
    pub package: Package,
    /// The ambient member's name resolutions.
    pub resolutions: Resolutions,
    /// The declaration-side prefix.
    pub decls: ServedDecls,
    /// The ambient's solved definition rows.
    pub effect_defs: Vec<DefEffects>,
    /// The ambient's solved method rows.
    pub effect_methods: Vec<ServedMethodRow>,
}

/// The artifact's payload: everything one served run needs, all of it
/// plain data (spans as `ds_diag::Span`, written types as ds-parse trees,
/// solved references as raw ids into the mint log's spaces).
#[derive(Serialize, Deserialize, Clone, Debug)]
pub struct AmbientDsi {
    /// The ambient member's namespace parts.
    pub package: PackageData,
    /// The ambient member's recorded uses, sorted by span.
    pub uses: Vec<UseData>,
    /// The universe's mint logs, memberships, and interned sets.
    pub universe: UniverseLog,
    /// The plain and signature declaration tables.
    pub decls: DeclsData,
    /// The instance environment's rows, in id order.
    pub instances: Vec<InstanceRowData>,
    /// The solved definition rows, in definition order.
    pub effects: Vec<DefRowData>,
    /// The solved method rows, in registration order.
    pub method_rows: Vec<MethodRowData>,
}

/// The namespace parts [`Package::add_file`] builds.
#[derive(Serialize, Deserialize, Clone, Debug)]
pub struct PackageData {
    /// The collected files, in addition order.
    pub files: Vec<FileId>,
    /// The definitions, in collection order.
    pub defs: Vec<DefData>,
    /// The type namespace: name to definition index.
    pub type_names: Vec<(String, u32)>,
    /// The value namespace: name to definition index.
    pub value_names: Vec<(String, u32)>,
    /// The registered methods, in registration order.
    pub methods: Vec<MethodDeclData>,
    /// The method-name index: name to candidate indexes.
    pub method_index: Vec<(String, Vec<u32>)>,
}

/// One package definition.
#[derive(Serialize, Deserialize, Clone, Debug)]
pub struct DefData {
    /// The declared name.
    pub name: String,
    /// What the declaration defines, as a [`DefKind`] discriminant.
    pub kind: u8,
    /// The defining name span.
    pub span: Span,
}

/// One registered method.
#[derive(Serialize, Deserialize, Clone, Debug)]
pub struct MethodDeclData {
    /// The method name.
    pub name: String,
    /// The owning trait or inherent impl target.
    pub owner: MethodOwnerData,
    /// The method's name span.
    pub span: Span,
}

/// The owner of a registered method.
#[derive(Serialize, Deserialize, Clone, Debug)]
pub enum MethodOwnerData {
    /// A trait member.
    Trait(u32),
    /// A function of an inherent impl over the named target type.
    Inherent(String),
}

/// One recorded name use.
#[derive(Serialize, Deserialize, Clone, Debug)]
pub struct UseData {
    /// The use's span.
    pub span: Span,
    /// What it resolved to.
    pub res: ResData,
}

/// The resolution of one name use.
#[derive(Serialize, Deserialize, Clone, Debug)]
pub enum ResData {
    /// A package-level definition.
    Def(u32),
    /// A local binder, by its introducing span.
    Local {
        /// The binder's span.
        bind: Span,
    },
    /// The `Trait::f` escape hatch.
    TraitMethod(u32),
    /// A dot-call's method position.
    Dot(DotResData),
    /// The `.err`/`.ok` handler surface form.
    Handler,
}

/// The resolution of a dot-call's method position.
#[derive(Serialize, Deserialize, Clone, Debug)]
pub enum DotResData {
    /// The free-function tier won.
    Free {
        /// The winning function's definition index.
        func: u32,
        /// The parameter the receiver feeds.
        fed_param: u32,
    },
    /// The registered method candidates.
    Methods {
        /// Candidate method indexes, in declaration order.
        candidates: Vec<u32>,
    },
    /// The type-keyed tier behind a type-name receiver.
    Static {
        /// Candidate method indexes.
        candidates: Vec<u32>,
    },
}

/// The universe's mint logs and interned sets: the reserve-phase atoms
/// in mint order (every def-named atom), the declared traits in order,
/// the trait memberships the skipped shape arms would have registered,
/// the shape-phase atom mints the skipped impl arms would have performed,
/// the interned member sets in intern order (the raw [`ds_check::Ty`]
/// indices every solved snapshot in the artifact names), and the shared
/// type-variable counter's settled value — all keyed by index against
/// the spaces the replays reproduce.
#[derive(Serialize, Deserialize, Clone, Debug)]
pub struct UniverseLog {
    /// The reserve-phase atoms, in mint order (the predeclared `none`
    /// excluded — `Universe::new` declares it).
    pub atoms: Vec<AtomEntry>,
    /// The declared traits, in declaration order.
    pub traits: Vec<String>,
    /// `(trait index, atom index)` membership records.
    pub memberships: Vec<(u32, u32)>,
    /// The shape-phase atom mints, in mint order: impl type variables
    /// and the structural atoms their head solving minted.
    pub mints: Vec<MintData>,
    /// The interned member sets, in intern order.
    pub sets: Vec<Vec<u32>>,
    /// The shared type-variable counter after the ambient's impl arms.
    pub var_counter: u32,
}

/// One shape-phase atom mint, the artifact's replay form of
/// [`ReplayMint`].
#[derive(Serialize, Deserialize, Clone, Debug)]
pub enum MintData {
    /// A minted impl type variable, under its unique name.
    Var(String),
    /// A structural tuple atom over its element atoms.
    Tuple(Vec<u32>),
    /// A structural application atom: constructor atom plus argument
    /// sets (raw intern indices).
    Apply {
        /// The constructor atom.
        ctor: u32,
        /// The argument sets, in position order.
        args: Vec<u32>,
    },
}

/// One minted atom and its final shape.
#[derive(Serialize, Deserialize, Clone, Debug)]
pub struct AtomEntry {
    /// The atom's declared name.
    pub name: String,
    /// Its final shape.
    pub shape: AtomShapeData,
}

/// An atom's final shape, the mint-log forms.
#[derive(Serialize, Deserialize, Clone, Debug)]
pub enum AtomShapeData {
    /// A unit tag.
    Unit,
    /// Identity allocated, shape pending (generic declarations).
    Reserved,
    /// A struct with its solved field signature.
    Struct(Vec<FieldData>),
    /// An enum with its case signature.
    Enum(Vec<CaseData>),
}

/// One field of a solved shape, as a type expression over the minted
/// ids.
#[derive(Serialize, Deserialize, Clone, Debug)]
pub struct FieldData {
    /// The field name; `None` marks a positional slot.
    pub name: Option<String>,
    /// The field's type expression.
    pub ty: TypeExprData,
}

/// One case of a solved enum shape.
#[derive(Serialize, Deserialize, Clone, Debug)]
pub struct CaseData {
    /// The case name.
    pub name: String,
    /// The payload fields.
    pub fields: Vec<FieldData>,
}

/// A type expression over the minted ids.
#[derive(Serialize, Deserialize, Clone, Debug)]
pub enum TypeExprData {
    /// A nominal atom.
    Atom(u32),
    /// A trait as a set.
    Trait(u32),
    /// A negated trait constraint.
    Not(u32),
    /// Union.
    Union(Box<Self>, Box<Self>),
    /// Intersection.
    Inter(Box<Self>, Box<Self>),
    /// Difference.
    Diff(Box<Self>, Box<Self>),
    /// A tuple.
    Tuple(Vec<Self>),
}

/// The plain and signature declaration tables, keyed by raw id.
#[derive(Serialize, Deserialize, Clone, Debug)]
pub struct DeclsData {
    /// Definition to atom identity.
    pub atoms: Vec<(u32, u32)>,
    /// Atom identity back to its definition.
    pub defs_of_atoms: Vec<(u32, u32)>,
    /// Definition to trait identity.
    pub traits: Vec<(u32, u32)>,
    /// Struct shapes (enum-case payload shapes included).
    pub structs: Vec<(u32, StructShapeData)>,
    /// Enum shapes.
    pub enums: Vec<(u32, EnumShapeData)>,
    /// Minted cases of non-generic enums.
    pub cases: Vec<(u32, CaseDeclData)>,
    /// Signatures of named functions and extern functions, by def.
    pub fns: Vec<(u32, FnSigData)>,
    /// Trait member signatures, by method id.
    pub members: Vec<(u32, FnSigData)>,
    /// Inherent impl-function signatures, by method id.
    pub inherent: Vec<(u32, FnSigData)>,
    /// Member names of each trait, by trait def.
    pub trait_members: Vec<(u32, Vec<String>)>,
    /// The defaulted member names of each trait, by trait def.
    pub trait_member_defaults: Vec<(u32, Vec<String>)>,
    /// Generic parameter names of each trait, by trait def.
    pub trait_generics: Vec<(u32, Vec<String>)>,
    /// The declaring impl item's span per served instance.
    pub instance_impls: Vec<(u32, Span)>,
    /// The impl item each served inherent impl function lives in.
    pub inherent_impls: Vec<(u32, Span)>,
}

/// A stored function signature, the artifact's form of [`FnSig`]: the
/// embedded written types and defaults serialize like the AST blob's
/// trees (they are ds-parse subtrees).
#[derive(Serialize, Deserialize, Clone, Debug)]
pub struct FnSigData {
    /// Declared generic parameters, in order.
    pub generics: Vec<GenericParamData>,
    /// Parameters, in order.
    pub params: Vec<ParamSigData>,
    /// The written return type; absent means inferred or unit.
    pub ret: Option<ds_parse::Type>,
}

/// One parameter of a stored signature, as written.
#[derive(Serialize, Deserialize, Clone, Debug)]
pub struct ParamSigData {
    /// Parameter name.
    pub name: String,
    /// Span of the name.
    pub span: Span,
    /// Passing mode (C2).
    pub mode: ds_parse::ParamMode,
    /// Written type; absent for inferred lambda parameters.
    pub ty: Option<ds_parse::Type>,
    /// Literal-only default (F7), as written.
    pub default: Option<ds_parse::Expr>,
}

/// One stored instance row: the written and solved halves of a
/// per-branch instance, the artifact's form of [`ServedInstance`] with
/// every solved snapshot a raw intern index.
#[derive(Serialize, Deserialize, Clone, Debug)]
pub struct InstanceRowData {
    /// The trait implemented.
    pub trait_id: u32,
    /// The branch as written, over the minted ids.
    pub head_expr: TypeExprData,
    /// The solved head, a raw intern index.
    pub head: u32,
    /// The declaration's written head pre-decomposition, a raw intern
    /// index.
    pub written: u32,
    /// The conditions this branch kept, as written.
    pub condition_exprs: Vec<(u32, TypeExprData)>,
    /// The kept conditions solved: `(trait, intern index)`.
    pub conditions: Vec<(u32, u32)>,
}

/// A struct's declared shape: generic parameters as written plus the
/// named fields as written.
#[derive(Serialize, Deserialize, Clone, Debug)]
pub struct StructShapeData {
    /// Generic parameters, in order.
    pub params: Vec<GenericParamData>,
    /// Named fields, in declaration order.
    pub fields: Vec<ds_parse::FieldDecl>,
    /// Whether the declaration subtracts copyability.
    pub linear: bool,
}

/// An enum's declared shape.
#[derive(Serialize, Deserialize, Clone, Debug)]
pub struct EnumShapeData {
    /// Generic parameters, in order.
    pub params: Vec<GenericParamData>,
    /// Cases, in declaration order.
    pub cases: Vec<EnumCaseData>,
    /// Whether the declaration subtracts copyability.
    pub linear: bool,
}

/// One declared generic parameter, as written.
#[derive(Serialize, Deserialize, Clone, Debug)]
pub struct GenericParamData {
    /// The parameter name.
    pub name: String,
    /// The name's span.
    pub span: Span,
    /// The declared bound, as written.
    pub bound: Option<ds_parse::Type>,
}

/// One enum case, as written.
#[derive(Serialize, Deserialize, Clone, Debug)]
pub struct EnumCaseData {
    /// The case name.
    pub name: String,
    /// The name's span.
    pub span: Span,
    /// The written payload.
    pub payload: ds_parse::EnumPayload,
}

/// One minted case of a non-generic enum.
#[derive(Serialize, Deserialize, Clone, Debug)]
pub struct CaseDeclData {
    /// The owning enum's definition index.
    pub enum_def: u32,
    /// The written payload.
    pub payload: ds_parse::EnumPayload,
}

/// One solved definition row.
#[derive(Serialize, Deserialize, Clone, Debug)]
pub struct DefRowData {
    /// The definition's index.
    pub def: u32,
    /// The declared name.
    pub name: String,
    /// What the definition is, as a [`DefKind`] discriminant.
    pub kind: u8,
    /// The defining name span.
    pub span: Span,
    /// The solved row's bits.
    pub row: u8,
    /// The solved capability bits.
    pub caps: u8,
}

/// One solved method row.
#[derive(Serialize, Deserialize, Clone, Debug)]
pub struct MethodRowData {
    /// The method's index.
    pub method: u32,
    /// The solved row's bits.
    pub row: u8,
    /// The solved capability bits.
    pub caps: u8,
}

/// The [`DefKind`] discriminants, in declaration order.
const DEF_KINDS: [DefKind; 9] = [
    DefKind::Fn,
    DefKind::Const,
    DefKind::Var,
    DefKind::Struct,
    DefKind::Enum,
    DefKind::Tag,
    DefKind::Case,
    DefKind::Trait,
    DefKind::TypeAlias,
];

fn kind_bits(kind: DefKind) -> u8 {
    DEF_KINDS
        .iter()
        .position(|&k| k == kind)
        .and_then(|p| u8::try_from(p).ok())
        .unwrap_or(0)
}

fn kind_of(bits: u8) -> Result<DefKind, AmbientDsiError> {
    DEF_KINDS
        .get(bits as usize)
        .copied()
        .ok_or(AmbientDsiError::Decode("unknown def kind"))
}

/// The artifact's bytes: source-hash header plus the postcard payload.
#[must_use]
pub fn artifact_bytes(artifact: &AmbientDsi) -> Vec<u8> {
    let mut bytes = Hash128::compute(crate::AMBIENT_SOURCE.as_bytes())
        .as_bytes()
        .to_vec();
    bytes.extend(postcard::to_allocvec(artifact).expect("the artifact serializes"));
    bytes
}

/// Generates the artifact from the current ambient source: parse,
/// derive-expansion, collect and resolve, the declaration phase alone
/// (the mint/set logs snapshot the phase boundary — the body pass
/// interns more sets), then the full analyze for the clean gate, the
/// effects pass, and the method rows — everything a served run must
/// reproduce. The ambient must check clean and resolve clean on its own
/// (the artifact serves a clean generation or nothing).
#[must_use]
pub fn generate() -> AmbientDsi {
    let mut files = ds_diag::Files::new();
    let file = files.add_source(crate::AMBIENT_FILE, crate::AMBIENT_SOURCE);
    let ast = ds_parse::parse(&files, file).expect("the ambient parses");
    let (expanded, diags) = ds_check::expand_derives(&[&ast]);
    assert!(diags.is_empty(), "the ambient derives refuse: {diags:?}");
    let tree = expanded.into_iter().next().expect("one");
    let mut package = Package::new();
    let mut resolve_diags = package.add_file(&tree);
    let (uses, mut file_diags) = package.resolve(&tree);
    resolve_diags.append(&mut file_diags);
    let tables = vec![uses];
    let (decls, decl_diags) = ds_check::decls::build(&package, &[&tree], &tables);
    assert!(
        decl_diags.is_empty(),
        "the ambient does not declare clean: {decl_diags:?}"
    );
    let analyzed = ds_check::analyze_resolved(
        &files,
        Arc::from(vec![tree]),
        package.into(),
        tables.into(),
        resolve_diags,
    );
    assert!(
        analyzed.checked.diags.is_empty(),
        "the ambient does not check clean: {:?}",
        analyzed.checked.diags
    );
    let rows = crate::declared_rows();
    let caps = crate::world_caps();
    let effects = ds_check::effects::effects_of_resolved(
        &analyzed.asts[..],
        &analyzed.package,
        &analyzed.resolutions[..],
        rows,
        caps,
    );
    let method_rows = ds_check::effects::solved_method_rows(
        &analyzed.asts[..],
        &analyzed.package,
        &analyzed.resolutions[..],
        rows,
        caps,
    );
    extract(&decls, &analyzed, &effects, &method_rows)
}

/// Extracts the artifact's tables from the ambient's declaration-phase
/// tables plus one finished ambient-only analyze (the namespace, uses,
/// and effect rows come from the analyze; every declaration table and
/// log from the phase snapshot). Deterministic by construction: every
/// list follows its table's id order or the walk's own order.
#[must_use]
pub fn extract(
    decls: &ds_check::Decls,
    analyzed: &Analyzed,
    effects: &Effects,
    method_rows: &[ServedMethodRow],
) -> AmbientDsi {
    let package = &analyzed.package;

    let mut type_names = Vec::new();
    let mut value_names = Vec::new();
    let defs: Vec<DefData> = package
        .defs()
        .iter()
        .enumerate()
        .map(|(index, def)| {
            let id = DefId::from_raw(u32::try_from(index).expect("def count fits u32"));
            if package.lookup_type(&def.name) == Some(id) {
                type_names.push((def.name.clone(), id.index()));
            }
            if package.lookup_value(&def.name) == Some(id) {
                value_names.push((def.name.clone(), id.index()));
            }
            DefData {
                name: def.name.clone(),
                kind: kind_bits(def.kind),
                span: def.span,
            }
        })
        .collect();
    let mut method_index: Vec<(String, Vec<u32>)> = Vec::new();
    // the name's row in `method_index`, so one pass builds the index
    // without a linear find per method
    let mut method_slots: HashMap<&str, usize> = HashMap::new();
    let methods: Vec<MethodDeclData> = package
        .methods()
        .iter()
        .enumerate()
        .map(|(index, method)| {
            let id = u32::try_from(index).expect("method count fits u32");
            let slot = *method_slots.entry(method.name.as_str()).or_insert_with(|| {
                method_index.push((method.name.clone(), vec![]));
                method_index.len() - 1
            });
            method_index[slot].1.push(id);
            MethodDeclData {
                name: method.name.clone(),
                owner: match &method.owner {
                    MethodOwner::Trait(def) => MethodOwnerData::Trait(def.index()),
                    MethodOwner::Inherent(target) => MethodOwnerData::Inherent(target.clone()),
                },
                span: method.span,
            }
        })
        .collect();

    let uses = analyzed.resolutions[0]
        .uses()
        .iter()
        .map(|(span, res)| UseData {
            span: *span,
            res: res_data(res),
        })
        .collect();

    AmbientDsi {
        package: PackageData {
            files: package.files().to_vec(),
            defs,
            type_names,
            value_names,
            methods,
            method_index,
        },
        uses,
        universe: universe_log(decls),
        decls: decls_data(decls),
        instances: instance_rows_of(decls),
        effects: effects
            .defs()
            .iter()
            .map(|row| DefRowData {
                def: row.def.index(),
                name: row.name.clone(),
                kind: kind_bits(row.kind),
                span: row.span,
                row: row.row.bits(),
                caps: row.caps,
            })
            .collect(),
        method_rows: method_rows
            .iter()
            .map(|row| MethodRowData {
                method: row.method.index(),
                row: row.row.bits(),
                caps: row.caps,
            })
            .collect(),
    }
}

/// The universe's mint logs and interned sets from the declaration-phase
/// snapshot: the def-named atoms with final shapes, the declared traits
/// in order, the trait memberships, the shape-phase mints, the interned
/// sets, and the settled variable counter.
fn universe_log(decls: &ds_check::Decls) -> UniverseLog {
    let universe = &decls.universe;
    let mut log = Vec::new();
    for id in universe.atom_ids() {
        if id == TypeId::NONE || !decls.defs_of_atoms.contains_key(&id) {
            continue;
        }
        let decl = universe.atom_decl(id).expect("every id has a decl");
        log.push(AtomEntry {
            name: decl.name.clone(),
            shape: match &decl.kind {
                AtomKind::Unit => AtomShapeData::Unit,
                AtomKind::Reserved => AtomShapeData::Reserved,
                AtomKind::Struct(fields) => {
                    AtomShapeData::Struct(fields.iter().map(field_data).collect())
                },
                AtomKind::Enum(cases) => AtomShapeData::Enum(cases.iter().map(case_data).collect()),
                AtomKind::Tuple(_) | AtomKind::Apply(..) | AtomKind::FnSig(..) => {
                    panic!("a def-named atom never carries a structural shape")
                },
            },
        });
    }
    assert_eq!(
        log.len(),
        decls.defs_of_atoms.len(),
        "the mint log must carry every def-named atom"
    );
    let mut memberships = Vec::new();
    for (_, &trait_id) in &decls.traits {
        let trait_decl = universe
            .trait_decl(trait_id)
            .expect("registered traits exist");
        for atom in &trait_decl.members {
            memberships.push((trait_id.index(), atom.index()));
        }
    }

    // The declared traits in declaration order (the serve replays them
    // before the memberships apply). The registry iterates by def id;
    // sorting by trait id restores the declaration order.
    let mut trait_rows: Vec<(u32, String)> = decls
        .traits
        .iter()
        .map(|(_, &trait_id)| {
            (
                trait_id.index(),
                universe
                    .trait_decl(trait_id)
                    .expect("registered traits exist")
                    .name
                    .clone(),
            )
        })
        .collect();
    trait_rows.sort_unstable();
    let traits: Vec<String> = trait_rows.into_iter().map(|(_, name)| name).collect();

    // The shape-phase mints: every atom the impl arms minted (variables
    // and structural atoms), in mint order.
    let mints: Vec<MintData> = universe
        .atom_ids()
        .filter(|id| *id != TypeId::NONE && !decls.defs_of_atoms.contains_key(id))
        .map(|id| {
            let decl = universe.atom_decl(id).expect("every id has a decl");
            match &decl.kind {
                AtomKind::Unit => MintData::Var(decl.name.clone()),
                AtomKind::Tuple(elements) => {
                    MintData::Tuple(elements.iter().map(|e| e.index()).collect())
                },
                AtomKind::Apply(ctor, args) => MintData::Apply {
                    ctor: ctor.index(),
                    args: args.iter().map(|ty| ty.index()).collect(),
                },
                AtomKind::Reserved
                | AtomKind::Struct(_)
                | AtomKind::Enum(_)
                | AtomKind::FnSig(..) => {
                    panic!("a shape-phase mint is a variable or structural atom")
                },
            }
        })
        .collect();

    // The interned sets in intern order: the raw Ty indices every solved
    // snapshot in the artifact names.
    let sets: Vec<Vec<u32>> = universe
        .set_log()
        .map(|members| members.iter().map(|atom| atom.index()).collect())
        .collect();

    UniverseLog {
        atoms: log,
        traits,
        memberships,
        mints,
        sets,
        var_counter: decls.var_counter,
    }
}

/// The plain and signature declaration tables from the declaration-phase
/// snapshot, every list in its table's id order.
fn decls_data(decls: &ds_check::Decls) -> DeclsData {
    let structs = decls
        .structs
        .iter()
        .map(|(def, shape)| {
            (def.index(), StructShapeData {
                params: shape.params.iter().map(generic_param_data).collect(),
                fields: shape.fields.clone(),
                linear: shape.linear,
            })
        })
        .collect();
    let enums = decls
        .enums
        .iter()
        .map(|(def, shape)| {
            (def.index(), EnumShapeData {
                params: shape.params.iter().map(generic_param_data).collect(),
                cases: shape
                    .cases
                    .iter()
                    .map(|(name, span, payload)| EnumCaseData {
                        name: name.clone(),
                        span: *span,
                        payload: payload.clone(),
                    })
                    .collect(),
                linear: shape.linear,
            })
        })
        .collect();
    let cases = decls
        .cases
        .iter()
        .map(|(def, case)| {
            (def.index(), CaseDeclData {
                enum_def: case.enum_def.index(),
                payload: case.payload.clone(),
            })
        })
        .collect();
    DeclsData {
        atoms: decls
            .atoms
            .iter()
            .map(|(def, atom)| (def.index(), atom.index()))
            .collect(),
        defs_of_atoms: decls
            .defs_of_atoms
            .iter()
            .map(|(atom, def)| (atom.index(), def.index()))
            .collect(),
        traits: decls
            .traits
            .iter()
            .map(|(def, trait_id)| (def.index(), trait_id.index()))
            .collect(),
        structs,
        enums,
        cases,
        fns: decls
            .fns
            .iter()
            .map(|(def, sig)| (def.index(), fn_sig_data(sig)))
            .collect(),
        members: decls
            .members
            .iter()
            .map(|(method, sig)| (method.index(), fn_sig_data(sig)))
            .collect(),
        inherent: decls
            .inherent
            .iter()
            .map(|(method, sig)| (method.index(), fn_sig_data(sig)))
            .collect(),
        trait_members: decls
            .trait_members
            .iter()
            .map(|(def, names)| (def.index(), names.clone()))
            .collect(),
        trait_member_defaults: decls
            .trait_member_defaults
            .iter()
            .map(|(def, names)| (def.index(), names.clone()))
            .collect(),
        trait_generics: decls
            .trait_generics
            .iter()
            .map(|(def, names)| (def.index(), names.clone()))
            .collect(),
        instance_impls: decls
            .instance_impls
            .iter()
            .map(|(id, span)| (id.index(), *span))
            .collect(),
        inherent_impls: decls
            .inherent_impls
            .iter()
            .map(|(method, span)| (method.index(), *span))
            .collect(),
    }
}

/// The instance rows, gated by the coherence skip's stability rule: a
/// head or condition naming a trait-relative set refuses the generation
/// (the serve's skip could not carry it).
fn instance_rows_of(decls: &ds_check::Decls) -> Vec<InstanceRowData> {
    (0..u32::try_from(decls.instances.len()).expect("instance count fits u32"))
        .map(|index| {
            let row = decls
                .instances
                .row(InstanceId::from_raw(index))
                .expect("every id has a row");
            assert_stable(&row.head_expr);
            for cond in &row.condition_exprs {
                assert_stable(&cond.ty);
            }
            instance_row_data(&row)
        })
        .collect()
}

fn generic_param_data(param: &ds_check::GenericParam) -> GenericParamData {
    GenericParamData {
        name: param.name.clone(),
        span: param.span,
        bound: param.bound.clone(),
    }
}

fn generic_param(data: &GenericParamData) -> ds_check::GenericParam {
    ds_check::GenericParam {
        name: data.name.clone(),
        span: data.span,
        bound: data.bound.clone(),
    }
}

fn fn_sig_data(sig: &FnSig) -> FnSigData {
    FnSigData {
        generics: sig.generics.iter().map(generic_param_data).collect(),
        params: sig
            .params
            .iter()
            .map(|param| ParamSigData {
                name: param.name.clone(),
                span: param.span,
                mode: param.mode,
                ty: param.ty.clone(),
                default: param.default.clone(),
            })
            .collect(),
        ret: sig.ret.clone(),
    }
}

fn fn_sig(data: &FnSigData) -> FnSig {
    FnSig {
        generics: data.generics.iter().map(generic_param).collect(),
        params: data
            .params
            .iter()
            .map(|param| ds_check::decls::ParamSig {
                name: param.name.clone(),
                span: param.span,
                mode: param.mode,
                ty: param.ty.clone(),
                default: param.default.clone(),
            })
            .collect(),
        ret: data.ret.clone(),
    }
}

fn instance_row_data(row: &ServedInstance) -> InstanceRowData {
    InstanceRowData {
        trait_id: row.trait_id.index(),
        head_expr: type_expr_data(&row.head_expr),
        head: row.head.index(),
        written: row.written.index(),
        condition_exprs: row
            .condition_exprs
            .iter()
            .map(|cond| (cond.trait_id.index(), type_expr_data(&cond.ty)))
            .collect(),
        conditions: row
            .conditions
            .iter()
            .map(|cond| (cond.trait_id.index(), cond.ty.index()))
            .collect(),
    }
}

/// Panics on a solved snapshot's written form naming a trait or a
/// negation: the only expressions whose solving membership growth widens,
/// which the served coherence skip cannot carry (the generator refuses
/// such an ambient until the serve learns to fall back).
fn assert_stable(expr: &TypeExpr) {
    match expr {
        TypeExpr::Trait(_) | TypeExpr::Not(_) => {
            panic!("a served instance head or condition names a trait-relative set")
        },
        TypeExpr::Union(a, b) | TypeExpr::Inter(a, b) | TypeExpr::Diff(a, b) => {
            assert_stable(a);
            assert_stable(b);
        },
        TypeExpr::Atom(_) => {},
        TypeExpr::Tuple(items) => {
            for item in items {
                assert_stable(item);
            }
        },
    }
}

fn field_data(field: &Field) -> FieldData {
    FieldData {
        name: field.name.clone(),
        ty: type_expr_data(&field.ty),
    }
}

fn case_data(case: &Case) -> CaseData {
    CaseData {
        name: case.name.clone(),
        fields: case.fields.iter().map(field_data).collect(),
    }
}

fn type_expr_data(expr: &TypeExpr) -> TypeExprData {
    match expr {
        TypeExpr::Atom(id) => TypeExprData::Atom(id.index()),
        TypeExpr::Trait(id) => TypeExprData::Trait(id.index()),
        TypeExpr::Not(id) => TypeExprData::Not(id.index()),
        TypeExpr::Union(a, b) => {
            TypeExprData::Union(Box::new(type_expr_data(a)), Box::new(type_expr_data(b)))
        },
        TypeExpr::Inter(a, b) => {
            TypeExprData::Inter(Box::new(type_expr_data(a)), Box::new(type_expr_data(b)))
        },
        TypeExpr::Diff(a, b) => {
            TypeExprData::Diff(Box::new(type_expr_data(a)), Box::new(type_expr_data(b)))
        },
        TypeExpr::Tuple(items) => TypeExprData::Tuple(items.iter().map(type_expr_data).collect()),
    }
}

fn res_data(res: &Res) -> ResData {
    match res {
        Res::Def(def) => ResData::Def(def.index()),
        Res::Local { bind } => ResData::Local { bind: *bind },
        Res::TraitMethod(method) => ResData::TraitMethod(method.index()),
        Res::Dot(dot) => ResData::Dot(match dot {
            ds_check::DotRes::Free { func, fed_param } => DotResData::Free {
                func: func.index(),
                fed_param: u32::try_from(*fed_param).expect("parameter index fits u32"),
            },
            ds_check::DotRes::Methods { candidates } => DotResData::Methods {
                candidates: candidates.iter().map(|m| m.index()).collect(),
            },
            ds_check::DotRes::Static { candidates } => DotResData::Static {
                candidates: candidates.iter().map(|m| m.index()).collect(),
            },
        }),
        Res::Handler => ResData::Handler,
    }
}

/// The verified artifact's native serve: the source-hash header must
/// match the current [`AMBIENT_SOURCE`](crate::AMBIENT_SOURCE), the
/// payload must decode, and the decoded tables must address exactly
/// `file` (the id the caller registered the ambient under — the standard
/// first-registered discipline, the same as the AST blob's). Any miss is
/// an error the caller answers with the fresh compute.
///
/// # Errors
///
/// [`AmbientDsiError`]: a stale header, a foreign file id, or a corrupt
/// payload — all of them cache misses, never source problems.
pub fn ambient_dsi(file: FileId) -> Result<ServedAmbient, AmbientDsiError> {
    let Some((header, payload)) = DSI.split_first_chunk::<HEADER>() else {
        return Err(AmbientDsiError::SourceDrift);
    };
    if header != Hash128::compute(crate::AMBIENT_SOURCE.as_bytes()).as_bytes() {
        return Err(AmbientDsiError::SourceDrift);
    }
    let artifact: AmbientDsi =
        postcard::from_bytes(payload).map_err(|_| AmbientDsiError::Decode("postcard refused"))?;
    if artifact.package.files.as_slice() != [file] {
        return Err(AmbientDsiError::FileMismatch);
    }
    serve(&artifact)
}

/// Converts the decoded artifact into the native serve.
fn serve(artifact: &AmbientDsi) -> Result<ServedAmbient, AmbientDsiError> {
    let package = serve_package(artifact)?;
    let resolutions = serve_resolutions(artifact);
    let (universe, tys) = serve_universe(artifact)?;
    let (decls, mints) = serve_tables(artifact, universe, &tys);

    let effect_defs = artifact
        .effects
        .iter()
        .map(|row| {
            Ok(DefEffects {
                def: DefId::from_raw(row.def),
                name: row.name.clone(),
                kind: kind_of(row.kind)?,
                span: row.span,
                row: ds_check::EffectRow::from_bits(row.row),
                caps: row.caps,
            })
        })
        .collect::<Result<Vec<_>, _>>()?;
    let effect_methods = artifact
        .method_rows
        .iter()
        .map(|row| ServedMethodRow {
            method: MethodId::from_raw(row.method),
            row: ds_check::EffectRow::from_bits(row.row),
            caps: row.caps,
        })
        .collect();

    Ok(ServedAmbient {
        package,
        resolutions,
        decls: ServedDecls {
            decls,
            memberships: artifact
                .universe
                .memberships
                .iter()
                .map(|(trait_id, atom)| (TraitId::from_raw(*trait_id), TypeId::from_raw(*atom)))
                .collect(),
            mints,
        },
        effect_defs,
        effect_methods,
    })
}

/// Rebuilds the namespace parts.
fn serve_package(artifact: &AmbientDsi) -> Result<Package, AmbientDsiError> {
    let defs = artifact
        .package
        .defs
        .iter()
        .map(|def| {
            Ok(Def {
                name: def.name.clone(),
                kind: kind_of(def.kind)?,
                span: def.span,
            })
        })
        .collect::<Result<Vec<_>, _>>()?;
    let methods = artifact
        .package
        .methods
        .iter()
        .map(|method| MethodDecl {
            name: method.name.clone(),
            owner: match &method.owner {
                MethodOwnerData::Trait(def) => MethodOwner::Trait(DefId::from_raw(*def)),
                MethodOwnerData::Inherent(target) => MethodOwner::Inherent(target.clone()),
            },
            span: method.span,
        })
        .collect();
    Ok(Package::from_parts(
        artifact.package.files.clone(),
        defs,
        artifact
            .package
            .type_names
            .iter()
            .map(|(name, id)| (name.clone(), DefId::from_raw(*id)))
            .collect(),
        artifact
            .package
            .value_names
            .iter()
            .map(|(name, id)| (name.clone(), DefId::from_raw(*id)))
            .collect(),
        methods,
        artifact
            .package
            .method_index
            .iter()
            .map(|(name, ids)| {
                (
                    name.clone(),
                    ids.iter()
                        .map(|&id| MethodId::from_raw(id))
                        .collect::<Vec<_>>(),
                )
            })
            .collect(),
    ))
}

/// Rebuilds the member's resolution table.
fn serve_resolutions(artifact: &AmbientDsi) -> Resolutions {
    Resolutions::from_uses(
        artifact
            .uses
            .iter()
            .map(|use_| {
                let res = match &use_.res {
                    ResData::Def(def) => Res::Def(DefId::from_raw(*def)),
                    ResData::Local { bind } => Res::Local { bind: *bind },
                    ResData::TraitMethod(method) => Res::TraitMethod(MethodId::from_raw(*method)),
                    ResData::Dot(dot) => Res::Dot(match dot {
                        DotResData::Free { func, fed_param } => ds_check::DotRes::Free {
                            func: DefId::from_raw(*func),
                            fed_param: *fed_param as usize,
                        },
                        DotResData::Methods { candidates } => ds_check::DotRes::Methods {
                            candidates: candidates
                                .iter()
                                .map(|&id| MethodId::from_raw(id))
                                .collect(),
                        },
                        DotResData::Static { candidates } => ds_check::DotRes::Static {
                            candidates: candidates
                                .iter()
                                .map(|&id| MethodId::from_raw(id))
                                .collect(),
                        },
                    }),
                    ResData::Handler => Res::Handler,
                };
                (use_.span, res)
            })
            .collect(),
    )
}

/// Replays the universe — the atom mint log, the trait declarations, the
/// interned sets — answering the raw [`ds_check::Ty`] values the solved
/// snapshots name.
fn serve_universe(artifact: &AmbientDsi) -> Result<(Universe, Vec<ds_check::Ty>), AmbientDsiError> {
    let corrupt = || AmbientDsiError::Decode("a table references an id out of its space");
    let mut universe = Universe::new();
    for atom in &artifact.universe.atoms {
        match &atom.shape {
            AtomShapeData::Unit => {
                universe.declare_tag(&atom.name).map_err(|_| corrupt())?;
            },
            AtomShapeData::Reserved => {
                universe.declare_struct(&atom.name).map_err(|_| corrupt())?;
            },
            AtomShapeData::Struct(fields) => {
                let id = universe.declare_struct(&atom.name).map_err(|_| corrupt())?;
                let converted: Vec<Field> = fields
                    .iter()
                    .map(|field| Field {
                        name: field.name.clone(),
                        ty: type_expr(&field.ty),
                    })
                    .collect();
                universe
                    .set_struct_fields(id, converted)
                    .map_err(|_| corrupt())?;
            },
            AtomShapeData::Enum(cases) => {
                let id = universe.declare_enum(&atom.name).map_err(|_| corrupt())?;
                let converted: Vec<Case> = cases
                    .iter()
                    .map(|case| Case {
                        name: case.name.clone(),
                        fields: case
                            .fields
                            .iter()
                            .map(|field| Field {
                                name: field.name.clone(),
                                ty: type_expr(&field.ty),
                            })
                            .collect(),
                    })
                    .collect();
                universe
                    .set_enum_cases(id, converted)
                    .map_err(|_| corrupt())?;
            },
        }
    }
    for name in &artifact.universe.traits {
        universe.declare_trait(name).map_err(|_| corrupt())?;
    }
    // The interned sets replay first (nothing else has interned yet, so
    // every replayed handle keeps its index), giving the raw Ty values
    // the solved snapshots and application mints below name.
    let mut tys = Vec::with_capacity(artifact.universe.sets.len());
    for set in &artifact.universe.sets {
        let members: Vec<TypeId> = set.iter().map(|&id| TypeId::from_raw(id)).collect();
        tys.push(universe.replay_set(&members));
    }
    Ok((universe, tys))
}

/// Installs the artifact's declaration tables over the replayed
/// universe, answering the shape-phase mints the build replays later.
fn serve_tables(
    artifact: &AmbientDsi,
    universe: Universe,
    tys: &[ds_check::Ty],
) -> (ds_check::Decls, Vec<ReplayMint>) {
    let mut decls = ds_check::Decls {
        universe,
        ..ds_check::Decls::default()
    };
    for (def, atom) in &artifact.decls.atoms {
        decls
            .atoms
            .insert(DefId::from_raw(*def), TypeId::from_raw(*atom));
    }
    for (atom, def) in &artifact.decls.defs_of_atoms {
        decls
            .defs_of_atoms
            .insert(TypeId::from_raw(*atom), DefId::from_raw(*def));
    }
    for (def, trait_id) in &artifact.decls.traits {
        decls
            .traits
            .insert(DefId::from_raw(*def), TraitId::from_raw(*trait_id));
    }
    for (def, shape) in &artifact.decls.structs {
        decls
            .structs
            .insert(DefId::from_raw(*def), ds_check::decls::StructShape {
                params: shape.params.iter().map(generic_param).collect(),
                fields: shape.fields.clone(),
                linear: shape.linear,
            });
    }
    for (def, shape) in &artifact.decls.enums {
        decls
            .enums
            .insert(DefId::from_raw(*def), ds_check::decls::EnumShape {
                params: shape.params.iter().map(generic_param).collect(),
                cases: shape
                    .cases
                    .iter()
                    .map(|case| (case.name.clone(), case.span, case.payload.clone()))
                    .collect(),
                linear: shape.linear,
            });
    }
    for (def, case) in &artifact.decls.cases {
        decls
            .cases
            .insert(DefId::from_raw(*def), ds_check::decls::CaseDecl {
                enum_def: DefId::from_raw(case.enum_def),
                payload: case.payload.clone(),
            });
    }
    for (def, sig) in &artifact.decls.fns {
        decls
            .fns
            .insert(DefId::from_raw(*def), Arc::new(fn_sig(sig)));
    }
    for (method, sig) in &artifact.decls.members {
        decls
            .members
            .insert(MethodId::from_raw(*method), Arc::new(fn_sig(sig)));
    }
    for (method, sig) in &artifact.decls.inherent {
        decls
            .inherent
            .insert(MethodId::from_raw(*method), Arc::new(fn_sig(sig)));
    }
    for (def, names) in &artifact.decls.trait_members {
        decls
            .trait_members
            .insert(DefId::from_raw(*def), names.clone());
    }
    for (def, names) in &artifact.decls.trait_member_defaults {
        decls
            .trait_member_defaults
            .insert(DefId::from_raw(*def), names.clone());
    }
    for (def, names) in &artifact.decls.trait_generics {
        decls
            .trait_generics
            .insert(DefId::from_raw(*def), names.clone());
    }
    for (instance, span) in &artifact.decls.instance_impls {
        decls
            .instance_impls
            .insert(InstanceId::from_raw(*instance), *span);
    }
    for (method, span) in &artifact.decls.inherent_impls {
        decls
            .inherent_impls
            .insert(MethodId::from_raw(*method), *span);
    }
    let rows: Vec<ServedInstance> = artifact
        .instances
        .iter()
        .map(|row| {
            let solved = |set: &u32| tys[*set as usize];
            ServedInstance {
                trait_id: TraitId::from_raw(row.trait_id),
                head_expr: type_expr(&row.head_expr),
                head: solved(&row.head),
                written: solved(&row.written),
                condition_exprs: row
                    .condition_exprs
                    .iter()
                    .map(|(trait_id, expr)| {
                        Condition::new(TraitId::from_raw(*trait_id), type_expr(expr))
                    })
                    .collect(),
                conditions: row
                    .conditions
                    .iter()
                    .map(|(trait_id, set)| {
                        Condition::new(TraitId::from_raw(*trait_id), solved(set))
                    })
                    .collect(),
            }
        })
        .collect();
    decls.instances.serve(rows);
    let mints: Vec<ReplayMint> = artifact
        .universe
        .mints
        .iter()
        .map(|mint| match mint {
            MintData::Var(name) => ReplayMint::Var(name.clone()),
            MintData::Tuple(elements) => {
                ReplayMint::Tuple(elements.iter().map(|&id| TypeId::from_raw(id)).collect())
            },
            MintData::Apply { ctor, args } => ReplayMint::Apply(
                TypeId::from_raw(*ctor),
                args.iter().map(|set| tys[*set as usize]).collect(),
            ),
        })
        .collect();
    decls.var_counter = artifact.universe.var_counter;
    decls.served_defs = u32::try_from(artifact.package.defs.len()).expect("def count fits u32");
    decls.served_methods =
        u32::try_from(artifact.package.methods.len()).expect("method count fits u32");
    (decls, mints)
}

fn type_expr(data: &TypeExprData) -> TypeExpr {
    match data {
        TypeExprData::Atom(id) => TypeExpr::Atom(TypeId::from_raw(*id)),
        TypeExprData::Trait(id) => TypeExpr::Trait(TraitId::from_raw(*id)),
        TypeExprData::Not(id) => TypeExpr::Not(TraitId::from_raw(*id)),
        TypeExprData::Union(a, b) => {
            TypeExpr::Union(Box::new(type_expr(a)), Box::new(type_expr(b)))
        },
        TypeExprData::Inter(a, b) => {
            TypeExpr::Inter(Box::new(type_expr(a)), Box::new(type_expr(b)))
        },
        TypeExprData::Diff(a, b) => TypeExpr::Diff(Box::new(type_expr(a)), Box::new(type_expr(b))),
        TypeExprData::Tuple(items) => TypeExpr::Tuple(items.iter().map(type_expr).collect()),
    }
}

/// The atom mint sequence of one finished universe, name plus shape per
/// index — the equivalence gate's comparable form (shapes through the
/// run's own universe where they name solved handles).
#[cfg(test)]
fn mint_facts(universe: &Universe) -> Vec<(String, String)> {
    universe
        .atom_ids()
        .enumerate()
        .map(|(index, id)| {
            let decl = universe.atom_decl(id).expect("every id has a decl");
            let shape = match &decl.kind {
                AtomKind::Unit => "unit".to_owned(),
                AtomKind::Reserved => "reserved".to_owned(),
                AtomKind::Struct(fields) => {
                    let parts: Vec<String> = fields
                        .iter()
                        .map(|field| {
                            format!("{}={:?}", field.name.clone().unwrap_or_default(), field.ty)
                        })
                        .collect();
                    format!("struct({})", parts.join(","))
                },
                AtomKind::Enum(cases) => {
                    let parts: Vec<String> = cases.iter().map(|case| case.name.clone()).collect();
                    format!("enum({})", parts.join(","))
                },
                AtomKind::Tuple(_) | AtomKind::Apply(..) | AtomKind::FnSig(..) => {
                    format!("{:?}", decl.kind)
                },
            };
            (format!("{index}:{}", decl.name), shape)
        })
        .collect()
}

#[cfg(test)]
mod tests {
    use super::*;

    /// A user file exercising the surface the serve must thread: a
    /// derive (whose synthesized impl the body pass checks against the
    /// served ambient's trait tables), a written trait impl and an
    /// inherent impl (instances and methods continuing the ambient's id
    /// spaces), and calls into ambient functions and traits.
    const USER: &str = "#[derive(show, hash)]\nstruct point { x: int, y: int }\n\nenum tone \
                        {\nwarm\ncool\n}\n\ntrait local { fn m(self) -> int }\n\nimpl local for \
                        tone {\nfn m(self) -> int { 3 }\n}\n\nimpl point {\nfn norm(self) -> int \
                        { (self.x * self.x + self.y * self.y) }\n}\n\nfn main() -> () {\nconst p \
                        = point { x: 3, y: 4 }\nconst t = warm\nprintln(\"${p.show()} ${p.norm()} \
                        ${t.m()} ${max(1, 2)}\")\n}\n";

    /// The embedded artifact must byte-match a fresh generation over the
    /// current source: any grammar, checker, resolution, effects, or
    /// format drift fails here until `cargo run -p ds-stdlib --example
    /// gen-ambient-dsi` regenerates it.
    #[test]
    fn the_artifact_matches_a_fresh_generation() {
        let fresh = artifact_bytes(&generate());
        assert_eq!(
            DSI[..HEADER],
            Hash128::compute(crate::AMBIENT_SOURCE.as_bytes()).as_bytes()[..],
            "the artifact's source hash drifted"
        );
        assert_eq!(
            &DSI[HEADER..],
            &fresh[HEADER..],
            "the checked-ambient artifact drifted; regenerate with `cargo run -p ds-stdlib \
             --example gen-ambient-dsi`"
        );
    }

    /// The served analyze answers the same bundle as the fresh analyze
    /// over the same ambient-plus-user program: identical trees,
    /// diagnostics, namespace, resolutions, universe mint sequence,
    /// plain declaration tables, instance environment, solved span-keyed
    /// records, and checked facts (the raw solved-handle comparisons are
    /// exact because the two runs mint identical sequences — the pin
    /// this gate enforces, failing loudly rather than drifting, should
    /// the artifact's log ever stop capturing the sequence).
    #[test]
    fn the_served_analyze_matches_a_fresh_analyze() {
        let mut files = ds_diag::Files::new();
        let ambient = files.add_source(crate::AMBIENT_FILE, crate::AMBIENT_SOURCE);
        let user = files.add_source("user.ds", USER);
        let user_ast = ds_parse::parse_script(&files, user).expect("the user source parses");

        // The served path: the blob tree first (pre-expanded), the
        // artifact's tables beside it.
        let served_tree = crate::ambient_ast(ambient).expect("the AST blob verifies");
        let served = ambient_dsi(ambient).expect("the artifact verifies");
        let served_run = ds_check::analyze_served(
            &files,
            vec![served_tree, user_ast.clone()],
            &[true, false],
            served.package,
            served.resolutions,
            served.decls,
        );
        assert!(
            served_run.checked.diags.is_empty(),
            "the served run must check clean: {:?}",
            served_run.checked.diags
        );

        // The fresh path over the same sources.
        let fresh_tree = ds_parse::parse(&files, ambient).expect("the ambient parses");
        let fresh_run =
            ds_check::analyze_owned(&files, vec![fresh_tree, user_ast], &[false, false]);
        assert!(
            fresh_run.checked.diags.is_empty(),
            "the fresh run must check clean: {:?}",
            fresh_run.checked.diags
        );

        assert_eq!(
            served_run.checked.diags, fresh_run.checked.diags,
            "both runs check the same program clean"
        );
        for (served_tree, fresh_tree) in served_run.asts.iter().zip(fresh_run.asts.iter()) {
            let served_bytes = postcard::to_allocvec(served_tree).expect("serializes");
            let fresh_bytes = postcard::to_allocvec(fresh_tree).expect("serializes");
            assert_eq!(
                served_bytes, fresh_bytes,
                "the trees must answer identically"
            );
        }
        assert_eq!(
            served_run.package, fresh_run.package,
            "the namespaces must match"
        );
        assert_eq!(
            served_run.resolutions[..],
            fresh_run.resolutions[..],
            "the resolutions must match"
        );
        assert_eq!(
            mint_facts(&served_run.decls.universe),
            mint_facts(&fresh_run.decls.universe),
            "the universe mint sequences must match"
        );

        // The plain tables, through the artifact's own comparable form
        // (postcard bytes: the embedded written types carry no equality).
        let served_tables = postcard::to_allocvec(&extract_tables(&served_run))
            .expect("the served tables serialize");
        let fresh_tables =
            postcard::to_allocvec(&extract_tables(&fresh_run)).expect("the fresh tables serialize");
        assert_eq!(
            served_tables, fresh_tables,
            "the plain declaration tables must match"
        );

        // The signature and trait-member tables, the same comparable
        // form (the embedded written types and defaults are ds-parse
        // subtrees, so the bytes pin them like the trees above).
        let served_sigs =
            postcard::to_allocvec(&sig_tables(&served_run)).expect("the served tables serialize");
        let fresh_sigs =
            postcard::to_allocvec(&sig_tables(&fresh_run)).expect("the fresh tables serialize");
        assert_eq!(served_sigs, fresh_sigs, "the signature tables must match");

        // The instance rows: written and solved halves both, the solved
        // halves raw (the mint sequences and intern orders agree).
        assert_eq!(
            instance_rows(&served_run),
            instance_rows(&fresh_run),
            "the instance rows must match"
        );

        // The serve must actually install its prefix: a marker regression
        // would rebuild everything fresh over the served tables and still
        // answer identically, so the pins trip it here.
        assert!(
            served_run.decls.served_defs > 0
                && served_run.decls.served_methods > 0
                && served_run.decls.instances.served_len() > 0,
            "the artifact's prefix must arrive served, not rebuilt"
        );

        // The trait registry.
        let served_traits = trait_facts(&served_run);
        let fresh_traits = trait_facts(&fresh_run);
        assert_eq!(
            served_traits, fresh_traits,
            "the trait registries must match"
        );

        // The solved span-keyed records (raw handles, same mint
        // sequences).
        assert_eq!(
            served_run.decls.trait_impl_args, fresh_run.decls.trait_impl_args,
            "the trait-reference arguments must match"
        );
        assert_eq!(
            served_run.decls.inherent_impl_bounds, fresh_run.decls.inherent_impl_bounds,
            "the inherent bounds must match"
        );
        assert_eq!(
            served_run.decls.impl_fn_rets, fresh_run.decls.impl_fn_rets,
            "the impl-member returns must match"
        );

        // The checked facts: top-level types raw, per-expression facts
        // rendered (Val carries no equality).
        assert_eq!(
            served_run.checked.def_types, fresh_run.checked.def_types,
            "the top-level types must match"
        );
        let served_exprs = rendered_exprs(&served_run);
        let fresh_exprs = rendered_exprs(&fresh_run);
        assert_eq!(
            served_exprs, fresh_exprs,
            "the checked expression facts must match"
        );

        // The effects: the served pass (user-only walk over the served
        // rows) must equal the fresh whole-package pass.
        let served_effects = ds_check::effects::effects_of_resolved_served(
            &served_run.asts[1..],
            &served_run.package,
            &served_run.resolutions[1..],
            &served.effect_defs,
            &served.effect_methods,
            crate::declared_rows(),
            crate::world_caps(),
        );
        let fresh_effects = ds_check::effects::effects_of_resolved(
            &fresh_run.asts[..],
            &fresh_run.package,
            &fresh_run.resolutions[..],
            crate::declared_rows(),
            crate::world_caps(),
        );
        assert_eq!(
            served_effects.defs(),
            fresh_effects.defs(),
            "the served effect rows must match the fresh pass"
        );
    }

    /// A file id the artifact was not generated under is a cache miss,
    /// never a serve.
    #[test]
    fn a_foreign_file_id_falls_back() {
        let Err(error) = ambient_dsi(FileId::new(9)) else {
            panic!("the artifact addresses its own file")
        };
        assert!(matches!(error, AmbientDsiError::FileMismatch));
    }

    /// A user program colliding with the served ambient keeps the fresh
    /// path's diagnostics: a redeclared ambient name still reports the
    /// duplicate at collection, and a user impl whose head overlaps a
    /// served instance still hits the fresh coherence path — its
    /// declaration probes against the installed served rows, and the
    /// closure pass keeps every pair a fresh row takes part in.
    #[test]
    fn a_user_collision_with_the_served_ambient_still_diagnoses() {
        const COLLIDE: &str = "fn println(msg: string) -> () { }\n\nimpl show for int {\nfn \
                               show(self) -> string { \"i\" }\n}\n";
        let mut files = ds_diag::Files::new();
        let ambient = files.add_source(crate::AMBIENT_FILE, crate::AMBIENT_SOURCE);
        let user = files.add_source("collide.ds", COLLIDE);
        let user_ast = ds_parse::parse_script(&files, user).expect("the user source parses");

        let served_tree = crate::ambient_ast(ambient).expect("the AST blob verifies");
        let served = ambient_dsi(ambient).expect("the artifact verifies");
        let served_run = ds_check::analyze_served(
            &files,
            vec![served_tree, user_ast.clone()],
            &[true, false],
            served.package,
            served.resolutions,
            served.decls,
        );
        assert!(
            !served_run.checked.diags.is_empty(),
            "the collision must diagnose"
        );

        let fresh_tree = ds_parse::parse(&files, ambient).expect("the ambient parses");
        let fresh_run =
            ds_check::analyze_owned(&files, vec![fresh_tree, user_ast], &[false, false]);
        assert_eq!(
            served_run.checked.diags, fresh_run.checked.diags,
            "the served run answers the fresh run's collision diagnostics"
        );
        assert!(
            served_run
                .checked
                .diags
                .iter()
                .any(|diag| diag.code == ds_diag::ErrorCode::DuplicateDefinition),
            "the redeclared ambient name reports the duplicate"
        );
        assert!(
            served_run
                .checked
                .diags
                .iter()
                .any(|diag| diag.code == ds_diag::ErrorCode::InstanceOverlap),
            "the overlapping user impl hits the coherence path"
        );
    }

    /// The plain tables of one run, in the artifact's comparable form
    /// (the signature tables ride in `sig_tables`, so they stay empty
    /// here — this view pins the plain tables alone).
    fn extract_tables(run: &Analyzed) -> DeclsData {
        let decls = &run.decls;
        DeclsData {
            atoms: decls
                .atoms
                .iter()
                .map(|(def, atom)| (def.index(), atom.index()))
                .collect(),
            defs_of_atoms: decls
                .defs_of_atoms
                .iter()
                .map(|(atom, def)| (atom.index(), def.index()))
                .collect(),
            traits: decls
                .traits
                .iter()
                .map(|(def, trait_id)| (def.index(), trait_id.index()))
                .collect(),
            structs: decls
                .structs
                .iter()
                .map(|(def, shape)| {
                    (def.index(), StructShapeData {
                        params: shape.params.iter().map(generic_param_data).collect(),
                        fields: shape.fields.clone(),
                        linear: shape.linear,
                    })
                })
                .collect(),
            enums: decls
                .enums
                .iter()
                .map(|(def, shape)| {
                    (def.index(), EnumShapeData {
                        params: shape.params.iter().map(generic_param_data).collect(),
                        cases: shape
                            .cases
                            .iter()
                            .map(|(name, span, payload)| EnumCaseData {
                                name: name.clone(),
                                span: *span,
                                payload: payload.clone(),
                            })
                            .collect(),
                        linear: shape.linear,
                    })
                })
                .collect(),
            cases: decls
                .cases
                .iter()
                .map(|(def, case)| {
                    (def.index(), CaseDeclData {
                        enum_def: case.enum_def.index(),
                        payload: case.payload.clone(),
                    })
                })
                .collect(),
            fns: Vec::new(),
            members: Vec::new(),
            inherent: Vec::new(),
            trait_members: Vec::new(),
            trait_member_defaults: Vec::new(),
            trait_generics: Vec::new(),
            instance_impls: Vec::new(),
            inherent_impls: Vec::new(),
        }
    }

    /// The signature and trait-member tables of one run, the artifact's
    /// comparable form.
    #[derive(Serialize)]
    struct SigTables {
        fns: Vec<(u32, FnSigData)>,
        members: Vec<(u32, FnSigData)>,
        inherent: Vec<(u32, FnSigData)>,
        trait_members: Vec<(u32, Vec<String>)>,
        trait_member_defaults: Vec<(u32, Vec<String>)>,
        trait_generics: Vec<(u32, Vec<String>)>,
        instance_impls: Vec<(u32, Span)>,
        inherent_impls: Vec<(u32, Span)>,
    }

    /// The signature and trait-member tables of one run, in id order.
    fn sig_tables(run: &Analyzed) -> SigTables {
        let decls = &run.decls;
        SigTables {
            fns: decls
                .fns
                .iter()
                .map(|(def, sig)| (def.index(), fn_sig_data(sig)))
                .collect(),
            members: decls
                .members
                .iter()
                .map(|(method, sig)| (method.index(), fn_sig_data(sig)))
                .collect(),
            inherent: decls
                .inherent
                .iter()
                .map(|(method, sig)| (method.index(), fn_sig_data(sig)))
                .collect(),
            trait_members: decls
                .trait_members
                .iter()
                .map(|(def, names)| (def.index(), names.clone()))
                .collect(),
            trait_member_defaults: decls
                .trait_member_defaults
                .iter()
                .map(|(def, names)| (def.index(), names.clone()))
                .collect(),
            trait_generics: decls
                .trait_generics
                .iter()
                .map(|(def, names)| (def.index(), names.clone()))
                .collect(),
            instance_impls: decls
                .instance_impls
                .iter()
                .map(|(id, span)| (id.index(), *span))
                .collect(),
            inherent_impls: decls
                .inherent_impls
                .iter()
                .map(|(method, span)| (method.index(), *span))
                .collect(),
        }
    }

    /// Every stored instance row of one run, serialized in id order (the
    /// written halves are the artifact's data form, so postcard bytes are
    /// the comparable shape).
    fn instance_rows(run: &Analyzed) -> Vec<u8> {
        let rows: Vec<InstanceRowData> = (0..u32::try_from(run.decls.instances.len())
            .expect("instance count fits u32"))
            .map(|index| {
                instance_row_data(
                    &run.decls
                        .instances
                        .row(InstanceId::from_raw(index))
                        .expect("every id has a row"),
                )
            })
            .collect();
        postcard::to_allocvec(&rows).expect("the instance rows serialize")
    }

    /// The trait registry of one run: index, name, member atoms.
    fn trait_facts(run: &Analyzed) -> Vec<(u32, String, Vec<u32>)> {
        let universe = &run.decls.universe;
        run.decls
            .traits
            .iter()
            .map(|(_, &trait_id)| {
                let decl = universe
                    .trait_decl(trait_id)
                    .expect("registered traits exist");
                (
                    trait_id.index(),
                    decl.name.clone(),
                    decl.members.iter().map(|atom| atom.index()).collect(),
                )
            })
            .collect()
    }

    /// Every checked expression fact rendered through its run's own
    /// universe: one line per span.
    fn rendered_exprs(run: &Analyzed) -> Vec<String> {
        let universe = &run.decls.universe;
        let mut facts: Vec<_> = run
            .checked
            .expr_types
            .iter()
            .map(|(span, val)| {
                format!(
                    "{}/{}/{} {} diverges={} poisoned={}",
                    span.file.as_u32(),
                    span.start,
                    span.end,
                    universe.render(val.ty),
                    val.diverges,
                    val.poisoned
                )
            })
            .collect();
        facts.sort_unstable();
        facts
    }
}
